require_once __DIR__.'/../includes/helpers.php'; require_role('archaeologist'); $title=t('nav.my_assessments'); $rows=fetch_all('SELECT fa.*,s.name site_name,s.city FROM ae_field_assessments fa JOIN ae_heritage_sites s ON s.id=fa.site_id WHERE fa.archaeologist_id=? ORDER BY fa.id DESC',[current_user()['id']]); include __DIR__.'/../includes/header.php';
?>
<section class="page-hero"><span class="eyebrow"><?= h(localized('متابعة التقييمات','Assessment Tracking')) ?></span><h1><?= h(t('nav.my_assessments')) ?></h1><p><?= h(localized('تعرض هذه الصفحة التقييمات التي أرسلتها وحالة مراجعتها.','This page shows your submitted assessments and their review status.')) ?></p></section>
<div class="table-card"><div class="table-responsive"><table class="table"><thead><tr><th><?= h(t('reports.site')) ?></th><th><?= h(localized('نوع الخطر','Risk Type')) ?></th><th><?= h(t('reports.risk')) ?></th><th><?= h(t('reports.recommendations')) ?></th><th><?= h(t('common.status')) ?></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= h($r['site_name']) ?></b><br><span class="mini"><?= h($r['city']) ?> — <?= h($r['visit_date']) ?></span></td><td><?= h($r['risk_type']) ?></td><td><span class="badge badge-<?= h(risk_class($r['risk_percentage'])) ?>"><?= (int)$r['risk_percentage'] ?>%</span></td><td><?= h(excerpt($r['recommendations'],90)) ?></td><td><span class="badge badge-neutral"><?= h(status_label($r['status'])) ?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty"><?= h(localized('لم ترسل أي تقييم بعد.','You have not submitted any assessments yet.')) ?></td></tr><?php endif; ?></tbody></table></div></div>
